"""Frozen risk-score falsification on nine previously selected correlated-noise groups."""
import argparse
from datetime import datetime,timezone
import json
from pathlib import Path
import numpy as np
from study_noise_neighbourhoods import ROOT,git,sha256
from study_noise_sure_feasibility import color
from study_noise_semantic_comparison import noise_model
from study_noise_connected_sure import centre_outputs,finite_score


def replay_noise(seed):
    a,_=np.random.SeedSequence(seed).spawn(2)
    return color(np.random.default_rng(a).standard_normal((3,64,64)))


def probe_set(seed):
    return color(np.random.default_rng(seed).standard_normal((8,3,64,64)))


def verify_replay(outputs,accepted,parent):
    if not accepted:raise ValueError('Known accepted group no longer accepted')
    for method,out in outputs.items():
        expected=parent['methods'][method]['1.0']['sampled_squared_error_per_plane']
        if not np.allclose(out*out,expected,rtol=1e-10,atol=1e-10):raise ValueError('Known group outputs changed')


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--data-version',type=int,required=True)
    args=parser.parse_args()
    if args.data_version<1:parser.error('Positive version required')
    names=('controle-biais-selection-bruit-v001-20261026T130217Z.json',
           'faisabilite-risque-connexe-bruit-v001-20261026T130936Z.json')
    paths=[ROOT/'docs/validation/raw'/n for n in names];hashes=[sha256(p) for p in paths]
    selection,risk=[json.loads(p.read_text(encoding='utf-8')) for p in paths]
    if sha256(ROOT/'tests/study_noise_connected_sure.py')!=risk['runner_sha256']:raise ValueError('Risk code changed')
    for n,h in risk['dependencies'].items():
        if sha256(ROOT/'tests'/n)!=h:raise ValueError('Risk dependency changed')
    cases=[r for r in selection['records'] if r['noise']=='binomial_correlated' and r['configuration']['family']=='flat']
    if len(cases)!=9 or risk['threshold']!=selection['threshold']:raise ValueError('Challenge population changed')
    start=datetime.now(timezone.utc);records=[];model=noise_model(True,False);threshold=risk['threshold']
    for index,parent in enumerate(cases):
        observed=replay_noise(parent['seed']);outputs,accepted=centre_outputs(observed,model,threshold)
        verify_replay(outputs,accepted,parent)
        residuals={m:(out-observed[:,32,32])**2 for m,out in outputs.items()}
        runs=[]
        for repeat in range(4):
            seed=261026300000+index*4+repeat;probes=probe_set(seed)
            scores={};switches={};terms_saved={}
            for epsilon in (.03,.15):
                terms={m:[] for m in outputs};switch_count=0
                for z in probes:
                    plus,ap=centre_outputs(observed+epsilon*z,model,threshold)
                    minus,am=centre_outputs(observed-epsilon*z,model,threshold)
                    switch_count+=int(ap!=accepted)+int(am!=accepted)
                    for m in outputs:terms[m].append((z[:,32,32]*(plus[m]-minus[m])/(2*epsilon)).tolist())
                scores[str(epsilon)]={m:{str(n):finite_score(residuals[m],terms[m],n) for n in (4,8)} for m in outputs}
                terms_saved[str(epsilon)]=terms;switches[str(epsilon)]=switch_count
            runs.append(dict(repeat=repeat,probe_seed=seed,scores=scores,directional_terms=terms_saved,activation_switches=switches))
        records.append(dict(noise_seed=parent['seed'],chosen_plane=parent['chosen_plane'],
            component_size=parent['component_size'],effective_support=parent['effective_support'],
            centre_outputs={m:out.tolist() for m,out in outputs.items()},
            true_squared_error_per_plane={m:(out*out).tolist() for m,out in outputs.items()},
            residual_squared={m:v.tolist() for m,v in residuals.items()},runs=runs))
        print('Known noise group',index+1,'of9 replayed and scored',flush=True)
    if [sha256(p) for p in paths]!=hashes:raise ValueError('Parents changed')
    now=datetime.now(timezone.utc)
    output=ROOT/'docs/validation/raw'/f"epreuve-risque-faux-groupes-bruit-v{args.data_version:03d}-{now.strftime('%Y%m%dT%H%M%SZ')}.json"
    result=dict(schema_version=1,data_version=args.data_version,campaign_id=output.stem,
        started_at_utc=start.isoformat(),completed_at_utc=now.isoformat(),commit=git('rev-parse','HEAD'),
        local_changes=git('status','--short').splitlines(),runner_sha256=sha256(Path(__file__)),numpy_version=np.__version__,
        parents=[dict(path=str(p),sha256=h) for p,h in zip(paths,hashes)],records=records,
        dependencies={n:sha256(ROOT/'tests'/n) for n in ('study_noise_connected_sure.py','study_noise_sure_feasibility.py','study_noise_semantic_comparison.py')},
        rules='Exactly9previouslyacceptedflatcorrelatedgroups,replaySeedSequence child0 and all3method squaredoutputs1e-10. Frozen prior detector,h.8,boundary/neffrules. Frozen matchedcovarianceprobes,eps.03/.15,nested4/8. Four independently seeded probe sets per SAME observation to audit estimator variability,not36independentimages. Recompute allweights/masks for plus/minus. Truth0for audit only,no epsilon/threshold/gain adjustment,no deployed selector.',
        limitations='Deliberately selectedknownfailures,notunbiasedrisk-validationpopulation,nofalsepositivefrequencyestimateornewindependentphotocorpus.9groups*4probe repeats are nested. Finite-difference scores on discontinuousestimator notguaranteedunbiased;no new correction. Safetyfalsification only,no production change.')
    with output.open('x',encoding='utf-8') as handle:json.dump(result,handle,ensure_ascii=False,indent=1,allow_nan=False)
    print(output,flush=True);print(len(records),'known cases,4probe repetitions each',flush=True)


if __name__=='__main__':main()
